const html = Bun.markdown.render("| a | b |\n| :-: | --: |\n| 1 | 2 |", {
  td: (children, meta?: Bun.markdown.CellMeta) =>
    `<td align="${meta?.align ?? "left"}">${children}</td>`,
  th: (children, meta?: Bun.markdown.CellMeta) =>
    `<th align="${meta?.align ?? "left"}">${children}</th>`,
});

function Td({ align, children }: Bun.markdown.CellProps & { children?: React.ReactNode }) {
  return <td style={{ textAlign: align ?? "left" }}>{children}</td>;
}
const el = Bun.markdown.react("| a |\n| -: |\n| 1 |", { td: Td });

function P({ children }: Bun.markdown.ChildrenProps) {
  return <p className="md-p">{children}</p>;
}
