const out = Bun.markdown.render("- [x] done\n- [ ] todo", {
  listItem: (children, meta: Bun.markdown.ListItemMeta) => {
    const n = meta.ordered ? `${(meta.start ?? 1) + meta.index}. ` : "";
    const box = meta.checked === undefined ? "" : meta.checked ? "[x] " : "[ ] ";
    return `${"  ".repeat(meta.depth)}${n}${box}${children}\n`;
  },
});

function Li({ checked, children }: Bun.markdown.ListItemProps & { children?: React.ReactNode }) {
  return <li data-checked={checked === undefined ? undefined : String(checked)}>{children}</li>;
}
const el = Bun.markdown.react("- [x] done", { li: Li });

const out = Bun.markdown.render("1. a\n2. b", {
  list: (children, meta: Bun.markdown.ListMeta) =>
    meta.ordered
      ? `<ol start="${meta.start ?? 1}" data-depth="${meta.depth}">${children}</ol>`
      : `<ul data-depth="${meta.depth}">${children}</ul>`,
});

